270	pub fn fold_journal_to_snapshot(
271	    events: &[crate::orch::OrchEvent],
272	    scalars: &JournalScalars,
273	) -> Result<TaskProgressSnapshot, BridgeError> {
274	    let mut checkpoints = Vec::new();
275	    let mut starts: Vec<(NodeId, i64)> = Vec::new();
276	
277	    for event in events {
278	        match &event.kind {
279	            crate::orch::OrchEventKind::NodeStarted { node } => {
280	                let node = NodeId::parse(node)?;
281	                starts.retain(|(started, _seq)| started != &node);
282	                starts.push((node, event.seq));
283	            }
284	            crate::orch::OrchEventKind::NodeFinished { node, ok, output } => {
285	                let node = NodeId::parse(node)?;
286	                starts.retain(|(started, _seq)| started != &node);
287	                checkpoints.push((node, output.clone(), *ok, event.seq));
288	            }
289	            crate::orch::OrchEventKind::Terminal { .. } => {
290	                starts.clear();
291	            }
292	            crate::orch::OrchEventKind::Progress { .. }
293	            | crate::orch::OrchEventKind::Usage { .. }
294	            | crate::orch::OrchEventKind::Plan { .. }
295	            | crate::orch::OrchEventKind::ToolCall { .. }
296	            | crate::orch::OrchEventKind::ToolCallUpdate { .. } => {}
297	        }
298	    }
299	
300	    // `cut_seq` is trusted verbatim from the tasks-row scalar (= `last_event_seq`), NOT clamped to
301	    // the max event seq. This relies on the load-bearing dual-store invariant: every sequenced
302	    // writer bumps `last_event_seq` THEN inserts its journal row at `seq == last_event_seq` in the
303	    // SAME transaction (SQLite) / under the SAME guard (Memory), so `cut_seq >= max journal seq`
304	    // always holds. A future writer that journals WITHOUT bumping `last_event_seq` would break this.
305	    Ok(TaskProgressSnapshot {
306	        status: scalars.status,
307	        result: scalars.result.clone(),
308	        error: scalars.error.clone(),
309	        checkpoints,
310	        starts,
311	        terminal_seq: scalars.terminal_seq,
312	        cut_seq: scalars.cut_seq,
313	    })
314	}
