/// A single node interleaved with a rich `ToolCall`+`ToolCallUpdate` pair:
/// node_started(1) tool_call(2,t1,in_progress) tool_call_update(3,t1->completed)
/// node_finished(4). The node start+finish on the SAME node collapses to just
/// `node_finished@4` (S6 fold); the tool call folds to ONE `tool_call` frame
/// carrying the merged (completed) state at its last-applied seq (3).
#[tokio::test]
async fn rich_snapshot_folds_toolcall_interleaved() {
    let store = std::sync::Arc::new(bridge_core::task_store::MemoryTaskStore::new());
    let task_id = bridge_core::ids::TaskId::parse("task-rich-golden").unwrap();
    store
        .create(&working_record("task-rich-golden"))
        .await
        .unwrap();
    let node_a = bridge_core::ids::NodeId::parse("a").unwrap();
    let op = operation_id_for_task(&task_id);
    let now = crate::workflow_sink::now_ms();

    let s1 = store
        .record_node_started(&task_id, &node_a, &op, now)
        .await
        .unwrap();
    let s2 = store
        .record_event_sequenced(
            &task_id,
            &op,
            now,
            bridge_core::orch::OrchEventKind::ToolCall {
                tool_call_id: "t1".into(),
                title: "read".into(),
                kind: "read".into(),
                status: "in_progress".into(),
                locations: vec![],
                content: None,
            },
        )
        .await
        .unwrap();
    let s3 = store
        .record_event_sequenced(
            &task_id,
            &op,
            now,
            bridge_core::orch::OrchEventKind::ToolCallUpdate {
                tool_call_id: "t1".into(),
                title: None,
                kind: None,
                status: Some("completed".into()),
                locations: None,
                content: None,
            },
        )
        .await
        .unwrap();
    let s4 = store
        .put_node_checkpoint_sequenced(&task_id, &node_a, &op, "out-a", true, now)
        .await
        .unwrap();
    assert_eq!((s1, s2, s3, s4), (1, 2, 3, 4));

    let store_dyn: std::sync::Arc<dyn bridge_core::task_store::TaskStore> = store;
    let folded = fold_or_typed_snapshot(&store_dyn, &task_id).await.unwrap();
    let frames = rich_snapshot_frames(&folded.snap, &folded.events, None);
    assert_eq!(tags(&frames), vec![(3, "tool_call"), (4, "node_finished")]);

    // The folded tool_call frame carries the MERGED current state (status
    // patched to "completed" by the update), not the original "in_progress".
    let crate::reattach::FrameKind::ToolCall { status, .. } = &frames[0].kind else {
        panic!("expected a folded ToolCall frame");
    };
    assert_eq!(status, "completed");
}

