fn orch_event(
    seq: i64,
    kind: bridge_core::orch::OrchEventKind,
) -> bridge_core::orch::OrchEvent {
    bridge_core::orch::OrchEvent {
        v: bridge_core::orch::ORCH_V,
        seq,
        ts_ms: 0,
        operation_id: bridge_core::ids::OperationId::parse("op-rich-fold-test").unwrap(),
        session: None,
        source: None,
        kind,
    }
}

/// A `ToolCallUpdate` with NO prior `ToolCall` base (a reattach whose cursor
/// already dropped the base row, or a genuinely out-of-order patch) is an
/// ORPHAN: it must fold to a `FrameKind::ToolCallUpdate` (sparse, unmerged)
/// rather than a `FrameKind::ToolCall` (which would fabricate a title/kind that
/// was never observed).
#[test]
fn fold_rich_frames_orphan_toolcall_update_emits_update_frame_not_toolcall() {
    let events = vec![orch_event(
        5,
        bridge_core::orch::OrchEventKind::ToolCallUpdate {
            tool_call_id: "orphan".into(),
            title: None,
            kind: None,
            status: Some("completed".into()),
            locations: None,
            content: None,
        },
    )];
    let frames = fold_rich_frames(&events);
    assert_eq!(frames.len(), 1);
    assert_eq!(frames[0].seq, 5);
    let crate::reattach::FrameKind::ToolCallUpdate {
        tool_call_id,
        status,
        title,
        ..
    } = &frames[0].kind
    else {
        panic!("expected an orphan ToolCallUpdate frame, got {:?}", frames[0].kind);
    };
    assert_eq!(tool_call_id, "orphan");
    assert_eq!(status.as_deref(), Some("completed"));
    assert!(title.is_none(), "no ToolCall base means no title to report");
}

/// Two `Plan` events for the same task keep ONLY the latest — an earlier plan
/// must not leak a stale frame into the transcript.
#[test]
fn fold_rich_frames_keeps_latest_plan_only() {
    let events = vec![
        orch_event(
            1,
            bridge_core::orch::OrchEventKind::Plan {
                entries: vec![bridge_core::orch::PlanEntry {
                    content: "stale step".into(),
                    priority: "low".into(),
                    status: "pending".into(),
                }],
            },
        ),
        orch_event(2, bridge_core::orch::OrchEventKind::Plan { entries: vec![] }),
    ];
    let frames = fold_rich_frames(&events);
    assert_eq!(frames.len(), 1, "the stale plan@1 must not survive: {frames:?}");
    assert_eq!(frames[0].seq, 2);
    let crate::reattach::FrameKind::Plan { entries } = &frames[0].kind else {
        panic!("expected a Plan frame");
    };
    assert!(entries.is_empty(), "must reflect the LATEST plan, not the stale one");
}

/// The cursor must be applied ONCE, over the MERGED node+rich list — not
/// separately per source. A cursor that sits between a rich frame's seq and a
/// node frame's seq must drop only the rich frame while keeping the node frame.
#[test]
fn rich_snapshot_frames_applies_cursor_once_over_merged_list() {
    let snap = bridge_core::task_store::TaskProgressSnapshot {
        status: bridge_core::task_store::TaskRecordStatus::Working,
        result: None,
        error: None,
        checkpoints: vec![(
            bridge_core::ids::NodeId::parse("a").unwrap(),
            "out".into(),
            true,
            4,
        )],
        starts: vec![],
        terminal_seq: None,
        cut_seq: 4,
    };
    let events = vec![orch_event(
        3,
        bridge_core::orch::OrchEventKind::ToolCall {
            tool_call_id: "t1".into(),
            title: "x".into(),
            kind: "read".into(),
            status: "in_progress".into(),
            locations: vec![],
            content: None,
        },
    )];
    // cursor == 3: rich tool_call@3 fails `seq > 3` and is dropped; the node
    // frame at seq 4 survives.
    let frames = rich_snapshot_frames(&snap, &events, Some(3));
    assert_eq!(tags(&frames), vec![(4, "node_finished")]);

    // No cursor: both frames appear, seq-ordered.
    let frames = rich_snapshot_frames(&snap, &events, None);
    assert_eq!(tags(&frames), vec![(3, "tool_call"), (4, "node_finished")]);
}

